// Characterization tests: pin the HTTP behaviour clients see today, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 2.5, C: 33.33, D: 100 }
const calls = []
const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order: 201, JSON, string id, echoed items', async () => {
  const items = [{ sku: 'A', qty: 2 }]
  const res = await post({ items })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const order = await res.json()
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(Object.keys(order).sort(), ['id', 'items', 'total'])
  assert.deepEqual(order.items, items)
  assert.equal(order.total, 20)
})

test('ids are distinct and sequential', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums price * qty across items, looking up each sku', async () => {
  calls.length = 0
  const order = await (await post({ items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 4 }] })).json()
  assert.equal(order.total, 30)
  assert.deepEqual(calls, ['A', 'B'])
})

test('total is floored to a whole number', async () => {
  const order = await (await post({ items: [{ sku: 'C', qty: 1 }] })).json()
  assert.equal(order.total, 33)
})

test('no discount at exactly 100', async () => {
  const order = await (await post({ items: [{ sku: 'D', qty: 1 }] })).json()
  assert.equal(order.total, 100)
})

test('10% discount when total exceeds 100, applied before flooring', async () => {
  const over = await (await post({ items: [{ sku: 'A', qty: 11 }] })).json()
  assert.equal(over.total, 99) // 110 -> 99
  const odd = await (await post({ items: [{ sku: 'C', qty: 4 }] })).json()
  assert.equal(odd.total, 119) // 133.32 * 0.9 = 119.988 -> 119
})

test('POST /orders rejects bad bodies with 400 and error message', async () => {
  const bad = [
    post({}), post({ items: [] }), post({ items: 'x' }), post(null, '{not json'),
    post(null, 'null'), post(null, ''),
  ]
  for (const res of await Promise.all(bad)) {
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'B', qty: 2 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order currently returns 200 with an error body (quirk)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods return 404 "no route"', async () => {
  const cases = [
    fetch(`${base}/`), fetch(`${base}/nope`), fetch(`${base}/orders`),
    fetch(`${base}/orders/1/extra`), fetch(`${base}/orders/1`, { method: 'DELETE' }),
    fetch(`${base}/orders/1`, { method: 'PUT' }),
  ]
  for (const res of await Promise.all(cases)) {
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
